        test('an UNFETCHABLE pull ref is a genuinely dead fork head (AC3)', function () {
            assert.equal(mod.classifyForkNoRef(false), 'dead',
                'fork deleted entirely — parks via the existing no-ref path, keyed on the pull ref');
        });
    });
});
