            assert.equal(mod.forkFullOf(forkItem({ headRepo: null }), BASE_OWNER, BASE_REPO), null);
            assert.equal(mod.forkFullOf(forkItem({ headRepo: '' }), BASE_OWNER, BASE_REPO), null);
