/** Minimal sm.json-style rule */
function makeRule(jql, overrides) {
    var base = {
        description: 'test rule',
        jql: jql,
        configFile: 'agents/test.json'
    };
    if (overrides) {
        for (var k in overrides) {
            if (overrides.hasOwnProperty(k)) base[k] = overrides[k];
        }
    }
    return base;
}

/** Base jobParams with owner/repo */
function baseParams(owner, repo, rules, extra) {
    var jobParams = {
        owner: owner || 'test-org',
        repo: repo || 'test-repo',
        rules: rules || []
    };
    if (extra) {
        for (var k in extra) {
            if (extra.hasOwnProperty(k)) jobParams[k] = extra[k];
        }
    }
    return { jobParams: jobParams };
}

