    var BASE_OWNER = 'epam';
    var BASE_REPO = 'dmtools-dart';
    var BASE_FULL = BASE_OWNER + '/' + BASE_REPO;
    var FORK_FULL = 'yuryby/dmtools-dart';
    var BRANCH = 'fix/android-dap-home-sandbox';

    function forkItem(extra) {
