            opts.onCliExecute = githubExtra.onCliExecute;
            delete github.onCliExecute;
        }
        return makeSmAgent(opts);
    }

    function triggerInputs(sm) {
        return sm.capturedTriggers.length ? JSON.parse(sm.capturedTriggers[0].inputs) : null;
    }

